<script setup lang="ts">
import { onMounted, ref } from 'vue';import { Play, RefreshCw, Rocket, RotateCcw } from '@lucide/vue';import { api } from '../services/http';import SectionHeader from './SectionHeader.vue';import EmptyState from './EmptyState.vue'
const gateway=ref<any>({});const agents=ref<any>({});const plugins=ref<any>({});const overview=ref<any>({});const about=ref<any>({});const update=ref<any>({});const status=ref('');const failed=ref(false);const detail=ref<any>(null)
function note(t:string,e=false){status.value=t;failed.value=e;setTimeout(()=>status.value='',5000)}
async function load(){try{const [g,a,p,o,ab,u]:any=await Promise.all([api('/api/v1/admin/gateway'),api('/api/v1/admin/agents'),api('/api/v1/admin/plugins'),api('/api/v1/admin/overview'),api('/api/v1/admin/about'),api('/api/v1/admin/update-status')]);gateway.value=g;agents.value=a;plugins.value=p;overview.value=o;about.value=ab;update.value=u}catch(e:any){note(e.message,true)}}
async function replay(row:any){const phrase=`REPLAY ${row.id}`;if(prompt(`输入确认短语：${phrase}`)!==phrase)return;try{await api(`/api/v1/admin/gateway/deliveries/${row.id}/replay`,{method:'POST',body:JSON.stringify({confirmation:phrase})});note('死信任务已重新排队');await load()}catch(e:any){note(e.message,true)}}
async function updateApp(){if(update.value.deployment_mode==='docker')return note(update.value.update_hint||'Docker 请在宿主机更新镜像',true);if(prompt('输入确认短语：UPDATE R20')!=='UPDATE R20')return;try{const d:any=await api('/api/v1/admin/update',{method:'POST',body:JSON.stringify({confirmation:'UPDATE R20'})});note((d.updated?'更新完成。':'当前已是最新。')+(d.restart_note||''));await load()}catch(e:any){note(e.message,true)}}
onMounted(load)
</script>
<template><div class="space-y-4"><div v-if="status" class="panel border-l-4 p-3 text-xs" :class="failed?'text-loss':'text-profit'">{{status}}</div><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article class="panel key-card p-4" :class="gateway.running?'key-card-profit':'key-card-loss'"><span class="data-pill" :class="gateway.running?'data-pill-profit':'data-pill-loss'"><span class="pulse-dot"></span>Gateway Worker</span><b class="key-number mt-4 block text-xl" :class="gateway.running?'text-profit':'text-loss'">{{gateway.running?'ONLINE':'OFFLINE'}}</b><p class="mt-2 text-[10px] muted">PID {{gateway.pid||'--'}} · v{{gateway.version}}</p></article><article v-for="(v,k) in gateway.stats||{}" :key="k" class="panel key-card key-card-brand p-4"><span class="data-pill data-pill-brand">{{k}}</span><b class="key-number mt-4 block text-2xl text-brand">{{v}}</b></article></section><section class="panel p-4 sm:p-5"><SectionHeader title="调度任务" subtitle="唯一 Gateway 调度所有者" :count="gateway.scheduler?.jobs?.length||0"><template #actions><button class="btn" @click="load"><RefreshCw :size="14"/>刷新</button></template></SectionHeader><div class="overflow-x-auto"><table class="terminal-table"><thead><tr><th>任务</th><th>脚本</th><th>计划</th><th>上次调度</th><th>状态</th></tr></thead><tbody><tr v-for="j in gateway.scheduler?.jobs||[]"><td><b>{{j.name}}</b></td><td class="font-mono muted">{{j.script}}</td><td>{{j.schedule}}</td><td>{{j.last_scheduled_at||'--'}}</td><td><span class="badge" :class="j.overdue?'badge-loss':'badge-profit'">{{j.overdue?'逾期':'正常'}}</span></td></tr></tbody></table></div></section><section class="panel p-4 sm:p-5"><SectionHeader title="事件投递队列" subtitle="失败投递、重试与死信重放" :count="gateway.deliveries?.length||0"/><div v-if="gateway.deliveries?.length" class="overflow-x-auto"><table class="terminal-table"><thead><tr><th>ID</th><th>频道</th><th>标题</th><th>状态</th><th>尝试</th><th>时间</th><th>操作</th></tr></thead><tbody><tr v-for="d in gateway.deliveries"><td>{{d.id}}</td><td>{{d.channel}}</td><td><button class="text-left text-brand" @click="detail=d">{{d.title||d.event_id}}</button></td><td><span class="badge" :class="d.status==='delivered'?'badge-profit':d.status==='dead'?'badge-loss':'badge-warning'">{{d.status}}</span></td><td>{{d.attempts}}</td><td>{{d.created_at}}</td><td><button v-if="d.status==='dead'" class="btn !min-h-8 !py-1" @click="replay(d)"><RotateCcw :size="12"/>重放</button></td></tr></tbody></table></div><EmptyState v-else text="当前没有事件投递记录"/></section><section class="panel p-4 sm:p-5"><SectionHeader title="Agent 与模型遥测" :subtitle="agents.prompt_policy" :count="agents.agents?.length||0"/><div class="grid gap-2.5 sm:grid-cols-2 xl:grid-cols-3"><article v-for="a in agents.agents||[]" class="subpanel key-card p-4" :class="a.health==='healthy'?'key-card-profit':a.health==='degraded'?'key-card-warning':'key-card-brand'"><div class="flex justify-between"><div><b>{{a.name}}</b><p class="mt-1 text-[9px] font-mono muted">{{a.id}}</p></div><span class="badge" :class="a.health==='healthy'?'badge-profit':a.health==='degraded'?'badge-warning':''">{{a.health}}</span></div><div class="mt-3 flex flex-wrap gap-2"><span class="data-pill">状态 <b>{{a.last_run_status}}</b></span><span class="data-pill">输出年龄 <b>{{a.output_age_seconds??'--'}}s</b></span></div></article></div><div class="mt-4 grid gap-3 sm:grid-cols-4"><div v-for="(v,k) in agents.model_stats||{}" class="subpanel p-3"><span class="label">{{k}}</span><b class="key-number text-brand">{{v}}</b></div></div><div class="mt-4 overflow-x-auto"><table class="terminal-table"><thead><tr><th>时间</th><th>调用方</th><th>模型</th><th>推理</th><th>状态</th><th>耗时</th><th>字符</th></tr></thead><tbody><tr v-for="m in agents.model_calls||[]"><td>{{m.started_at}}</td><td>{{m.caller}}</td><td>{{m.model}}</td><td>{{m.reasoning_effort}}</td><td>{{m.status}}</td><td>{{m.duration_ms}}ms</td><td>{{m.input_chars}} → {{m.output_chars}}</td></tr><tr v-if="!agents.model_calls?.length"><td colspan="7" class="muted">等待下一次模型调用遥测</td></tr></tbody></table></div></section><section class="panel p-4 sm:p-5"><SectionHeader title="内置插件" :subtitle="plugins.reason" :count="plugins.plugins?.length||0"/><div class="grid gap-2.5 sm:grid-cols-2 xl:grid-cols-3"><article v-for="p in plugins.plugins||[]" class="subpanel p-4"><div class="flex justify-between"><b>{{p.name||p.id}}</b><span class="badge" :class="p.enabled===false?'badge-loss':'badge-profit'">{{p.enabled===false?'禁用':'可用'}}</span></div><p class="mt-2 text-[10px] muted">{{p.description||p.type||'builtin-only'}}</p></article></div></section><section class="grid gap-4 xl:grid-cols-2"><div class="panel p-4"><SectionHeader title="产品与运行环境"/><div class="grid gap-2 sm:grid-cols-2"><div class="subpanel p-3"><span class="label">产品</span><b>{{about.product?.name}} {{about.product?.version}}</b></div><div class="subpanel p-3"><span class="label">Python / 平台</span><b class="text-xs">{{about.runtime?.python}} · {{about.runtime?.platform}}</b></div><div class="subpanel p-3"><span class="label">仓库</span><b class="text-xs font-mono">{{about.repository?.branch}} · {{about.repository?.commit}}</b></div><div class="subpanel p-3"><span class="label">认证</span><b class="text-xs">{{about.security?.authentication}}</b></div></div></div><div class="panel p-4"><SectionHeader title="应用更新"><template #actions><button class="btn btn-primary" @click="updateApp"><Rocket :size="14"/>检查并更新</button></template></SectionHeader><div class="grid grid-cols-2 gap-2"><div class="subpanel p-3"><span class="label">本地</span><b class="font-mono text-brand">{{update.local}}</b></div><div class="subpanel p-3"><span class="label">远程</span><b class="font-mono">{{update.remote||'镜像管理'}}</b></div><div class="subpanel p-3"><span class="label">落后</span><b>{{update.behind||0}}</b></div><div class="subpanel p-3"><span class="label">工作区</span><b :class="update.dirty?'text-warning':'text-profit'">{{update.dirty?'有修改':'干净'}}</b></div></div><p v-if="update.update_hint" class="mt-3 text-[10px] muted">{{update.update_hint}}</p></div></section><div v-if="detail" class="fixed inset-0 z-50 grid place-items-center bg-black/70 p-4" @click.self="detail=null"><div class="panel max-h-[80vh] w-full max-w-2xl overflow-auto p-5"><div class="flex justify-between"><b>投递详情 #{{detail.id}}</b><button class="btn" @click="detail=null">关闭</button></div><pre class="subpanel mt-3 whitespace-pre-wrap p-4 text-[11px]">{{JSON.stringify(detail,null,2)}}</pre></div></div></div></template>
